<?php require 'inc.php';
if(post()){$fat=(float)$_POST['fat'];$tmp=(float)$_POST['tmp'];$ad=(int)$_POST['ad'];$ok=!$ad&&$fat>=3.0&&$tmp<=10;
 q('INSERT INTO quality_test(delivery_id,tested_by,fat_percent,temperature,adulterated,result,grade) VALUES(?,?,?,?,?,?,?)',[$_POST['id'],$_SESSION['uid'],$fat,$tmp,$ad,$ok?'Accepted':'Rejected',$ok?($fat>=3.5?'A':'B'):'-']);flash('Test saved: '.($ok?'Accepted':'Rejected'));}
start('Quality tests');?><p>Rule: rejected if fat is below 3.0%, temperature is above 10 C, or the milk is adulterated. Fat of 3.5% or more is Grade A, otherwise Grade B.</p>
<div class="card wrap"><table><tr><th>Delivery</th><th>Farmer</th><th>Litres</th><th colspan="4">Test</th></tr><?php foreach(q('SELECT d.delivery_id,d.litres,m.full_name FROM delivery d JOIN member m USING(member_id) LEFT JOIN quality_test t USING(delivery_id) WHERE t.test_id IS NULL ORDER BY d.delivery_id') as $d)
echo '<form method="post"><tr><td>'.$d['delivery_id'].'<input type="hidden" name="id" value="'.$d['delivery_id'].'"></td><td>'.e($d['full_name']).'</td><td>'.$d['litres'].'</td><td><input name="fat" type="number" step="0.1" placeholder="Fat %" required style="width:80px"></td><td><input name="tmp" type="number" step="0.1" placeholder="Temp C" required style="width:80px"></td><td><select name="ad"><option value="0">Not adulterated</option><option value="1">Adulterated</option></select></td><td><button>Save</button></td></tr></form>';?></table></div><?php done();
